alter table cashbox add column if not exists current_balance numeric(24,6)not null default 0,add column if not exists status text not null default'CERRADA',add column if not exists responsible_user_id bigint references users;
alter table cash_transaction add column if not exists reference text,add column if not exists offset_account_id bigint references chart_accounts,add column if not exists created_by bigint references users,add column if not exists created_at timestamptz not null default now();
alter table cash_opening add column if not exists status text not null default'ABIERTA',add column if not exists closing_id bigint;
alter table cash_closing add column if not exists expected_amount numeric(24,6),add column if not exists note text;
alter table cash_transfer add column if not exists concept text,add column if not exists created_by bigint references users;
create table if not exists treasury_schedule(schedule_id bigint generated always as identity primary key,subsidiary_id bigint not null references subsidiaries,schedule_type text not null check(schedule_type in('PAYMENT','COLLECTION')),supplier_id bigint references suppliers,customer_id bigint references customers,supplier_invoice_id bigint references supplier_invoice,invoice_id bigint references invoice,due_date date not null,planned_date date not null,amount numeric(24,6)not null check(amount>0),currency_id bigint not null references currencies,priority text not null default'MEDIA'check(priority in('ALTA','MEDIA','BAJA')),status text not null default'PROGRAMADO'check(status in('PROGRAMADO','EJECUTADO','CANCELADO')),note text,created_by bigint references users,created_at timestamptz not null default now(),check((schedule_type='PAYMENT'and supplier_id is not null and customer_id is null)or(schedule_type='COLLECTION'and customer_id is not null and supplier_id is null)));
create index if not exists treasury_schedule_scope_idx on treasury_schedule(subsidiary_id,planned_date,status,schedule_type);
alter table treasury_schedule enable row level security;drop policy if exists treasury_schedule_access on treasury_schedule;create policy treasury_schedule_access on treasury_schedule for all to authenticated using(subsidiary_id=active_subsidiary_id())with check(subsidiary_id=active_subsidiary_id());grant select,insert,update,delete on treasury_schedule to authenticated;grant usage,select on sequence treasury_schedule_schedule_id_seq to authenticated;

create or replace function treasury_workspace(p_filters jsonb default'{}')returns jsonb language sql stable security definer set search_path=public as $$with s as(select*from subsidiaries where subsidiary_id=active_subsidiary_id()),dates as(select coalesce(nullif(p_filters->>'from','')::date,current_date)df,coalesce(nullif(p_filters->>'to','')::date,current_date+interval'90 days')::date dt),bank as(select coalesce(sum(ba.balance*case when ba.currency_id=s.currency_id then 1 else coalesce((select er.spot_rate from exchange_rates er where er.from_currency_id=ba.currency_id and er.to_currency_id=s.currency_id and er.effective_date<=current_date order by er.effective_date desc limit 1),1)end),0)total from bank_account ba,s where ba.subsidiary_id=s.subsidiary_id),cash as(select coalesce(sum(cb.current_balance*case when cb.currency_id=s.currency_id then 1 else coalesce((select er.spot_rate from exchange_rates er where er.from_currency_id=cb.currency_id and er.to_currency_id=s.currency_id and er.effective_date<=current_date order by er.effective_date desc limit 1),1)end),0)total from cashbox cb,s where cb.subsidiary_id=s.subsidiary_id)
select jsonb_build_object('subsidiary',jsonb_build_object('id',s.subsidiary_id,'name',s.name,'currencyId',s.currency_id,'currency',cu.currency_code),'location',(select jsonb_build_object('id',location_id,'name',name)from locations where subsidiary_id=s.subsidiary_id order by location_id limit 1),'cashboxes',coalesce((select jsonb_agg(jsonb_build_object('id',cb.cashbox_id,'name',cb.cashbox_name,'locationId',cb.location_id,'location',l.name,'currencyId',cb.currency_id,'currency',c.currency_code,'accountId',cb.account_id,'balance',cb.current_balance,'status',cb.status)order by cb.cashbox_name)from cashbox cb join locations l using(location_id)join currencies c using(currency_id)where cb.subsidiary_id=s.subsidiary_id),'[]'),'bankAccounts',coalesce((select jsonb_agg(jsonb_build_object('id',ba.bank_account_id,'bank',b.bank_name,'number',ba.account_number,'currency',c.currency_code,'balance',ba.balance))from bank_account ba join banks b using(bank_id)join currencies c using(currency_id)where ba.subsidiary_id=s.subsidiary_id),'[]'),'currencies',coalesce((select jsonb_agg(jsonb_build_object('id',c.currency_id,'code',c.currency_code))from subsidiary_currencies sc join currencies c using(currency_id)where sc.subsidiary_id=s.subsidiary_id),'[]'),'accounts',coalesce((select jsonb_agg(jsonb_build_object('id',ca.account_id,'number',ca.account_number,'name',ca.account_name))from chart_accounts ca join account_subsidiaries a using(account_id)where a.subsidiary_id=s.subsidiary_id and a.is_active and ca.accepts_entries and not ca.is_inactive),'[]'),'periods',coalesce((select jsonb_agg(jsonb_build_object('id',fiscal_period_id,'name',period_name,'start',start_date,'end',end_date))from fiscal_periods where subsidiary_id=s.subsidiary_id and not is_closed),'[]'),'movements',coalesce((select jsonb_agg(jsonb_build_object('id',ct.cash_tran_id,'date',ct.tran_date,'cashbox',cb.cashbox_name,'type',ct.type,'amount',ct.amount,'concept',ct.concept,'reference',ct.reference)order by ct.tran_date desc,ct.cash_tran_id desc)from cash_transaction ct join cashbox cb using(cashbox_id),dates where cb.subsidiary_id=s.subsidiary_id and ct.tran_date between dates.df and dates.dt),'[]'),'schedules',coalesce((select jsonb_agg(jsonb_build_object('id',ts.schedule_id,'type',ts.schedule_type,'party',coalesce(sp.company_name,c.company_name),'document',coalesce(si.invoice_number,i.invoice_number),'dueDate',ts.due_date,'plannedDate',ts.planned_date,'amount',ts.amount,'currency',cu2.currency_code,'priority',ts.priority,'status',ts.status,'note',ts.note)order by ts.planned_date,ts.priority)from treasury_schedule ts left join suppliers sp using(supplier_id)left join customers c using(customer_id)left join supplier_invoice si on si.invoice_id=ts.supplier_invoice_id left join invoice i on i.invoice_id=ts.invoice_id join currencies cu2 on cu2.currency_id=ts.currency_id,dates where ts.subsidiary_id=s.subsidiary_id and ts.planned_date between dates.df and dates.dt),'[]'),'payables',coalesce((select jsonb_agg(jsonb_build_object('id',si.invoice_id,'partyId',si.supplier_id,'party',sp.company_name,'number',si.invoice_number,'dueDate',si.due_date,'amount',greatest(si.total_amount-coalesce(a.paid,0),0),'currencyId',si.currency_id,'currency',c.currency_code))from supplier_invoice si join suppliers sp on sp.supplier_id=si.supplier_id join currencies c on c.currency_id=si.currency_id left join lateral(select sum(amount)paid from supplier_payment_application where invoice_id=si.invoice_id)a on true where si.subsidiary_id=s.subsidiary_id and si.total_amount>coalesce(a.paid,0)),'[]'),'receivables',coalesce((select jsonb_agg(jsonb_build_object('id',i.invoice_id,'partyId',i.customer_id,'party',c.company_name,'number',i.invoice_number,'dueDate',i.due_date,'amount',greatest(i.total_amount-coalesce(a.paid,0),0),'currencyId',i.currency_id,'currency',cu3.currency_code))from invoice i join customers c on c.customer_id=i.customer_id join currencies cu3 on cu3.currency_id=i.currency_id left join lateral(select sum(amount)paid from customer_payment_application where invoice_id=i.invoice_id)a on true where i.subsidiary_id=s.subsidiary_id and i.total_amount>coalesce(a.paid,0)),'[]'),'position',jsonb_build_object('banks',bank.total,'cash',cash.total,'available',bank.total+cash.total),'forecast',coalesce((select jsonb_agg(x order by x->>'date')from(select jsonb_build_object('date',planned_date,'collections',sum(amount)filter(where schedule_type='COLLECTION'and status='PROGRAMADO'),'payments',sum(amount)filter(where schedule_type='PAYMENT'and status='PROGRAMADO'))x from treasury_schedule,dates where subsidiary_id=s.subsidiary_id and planned_date between dates.df and dates.dt group by planned_date)q),'[]'))from s join currencies cu on cu.currency_id=s.currency_id,bank,cash$$;

create or replace function save_treasury_operation(p_payload jsonb)returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$declare sid bigint:=active_subsidiary_id();op text:=p_payload->>'operation';box cashbox%rowtype;other cashbox%rowtype;amt numeric:=coalesce(nullif(p_payload->>'amount','')::numeric,0);actual numeric;id bigint;
begin if op='CREATE_CASHBOX'then insert into cashbox(cashbox_name,subsidiary_id,location_id,currency_id,account_id,current_balance,status)values(trim(p_payload->>'name'),sid,(p_payload->>'location_id')::bigint,(p_payload->>'currency_id')::bigint,(p_payload->>'account_id')::bigint,0,'CERRADA')returning cashbox_id into id;return jsonb_build_object('id',id,'message','Caja creada correctamente.');end if;select*into box from cashbox where cashbox_id=(p_payload->>'cashbox_id')::bigint and subsidiary_id=sid for update;if box.cashbox_id is null then raise exception'Caja no encontrada.';end if;if op='OPEN'then if box.status='ABIERTA'then raise exception'La caja ya está abierta.';end if;insert into cash_opening(opening_date,cashbox_id,user_id,initial_amount,status)values((p_payload->>'date')::date,box.cashbox_id,app_user_id(),amt,'ABIERTA')returning opening_id into id;update cashbox set current_balance=amt,status='ABIERTA',responsible_user_id=app_user_id()where cashbox_id=box.cashbox_id;return jsonb_build_object('id',id,'message','Caja abierta correctamente.');elsif op='MOVEMENT'then if box.status<>'ABIERTA'then raise exception'La caja debe estar abierta.';end if;if p_payload->>'movement_type'='SALIDA'and box.current_balance<amt then raise exception'Saldo insuficiente. Disponible %.',box.current_balance;end if;insert into cash_transaction(tran_date,cashbox_id,amount,type,concept,reference,offset_account_id,created_by)values((p_payload->>'date')::date,box.cashbox_id,amt,p_payload->>'movement_type',p_payload->>'concept',p_payload->>'reference',nullif(p_payload->>'offset_account_id','')::bigint,app_user_id())returning cash_tran_id into id;update cashbox set current_balance=current_balance+case when p_payload->>'movement_type'='ENTRADA'then amt else-amt end where cashbox_id=box.cashbox_id;return jsonb_build_object('id',id,'message','Movimiento registrado correctamente.');elsif op='TRANSFER'then select*into other from cashbox where cashbox_id=(p_payload->>'target_cashbox_id')::bigint and subsidiary_id=sid for update;if other.cashbox_id is null or other.cashbox_id=box.cashbox_id then raise exception'Seleccione otra caja destino.';end if;if box.status<>'ABIERTA'or other.status<>'ABIERTA'then raise exception'Ambas cajas deben estar abiertas.';end if;if box.currency_id<>other.currency_id then raise exception'Las transferencias entre cajas deben usar la misma moneda.';end if;if box.current_balance<amt then raise exception'Saldo insuficiente en caja origen.';end if;insert into cash_transfer(transfer_date,amount,from_cashbox_id,to_cashbox_id,concept,created_by)values((p_payload->>'date')::date,amt,box.cashbox_id,other.cashbox_id,p_payload->>'concept',app_user_id())returning transfer_id into id;update cashbox set current_balance=current_balance-amt where cashbox_id=box.cashbox_id;update cashbox set current_balance=current_balance+amt where cashbox_id=other.cashbox_id;return jsonb_build_object('id',id,'message','Transferencia realizada correctamente.');elsif op='CLOSE'then if box.status<>'ABIERTA'then raise exception'La caja no está abierta.';end if;actual:=(p_payload->>'actual_amount')::numeric;insert into cash_closing(closing_date,cashbox_id,user_id,final_amount,expected_amount,difference,note)values((p_payload->>'date')::date,box.cashbox_id,app_user_id(),actual,box.current_balance,actual-box.current_balance,p_payload->>'concept')returning closing_id into id;update cashbox set current_balance=actual,status='CERRADA',responsible_user_id=null where cashbox_id=box.cashbox_id;update cash_opening set status='CERRADA',closing_id=id where opening_id=(select opening_id from cash_opening where cashbox_id=box.cashbox_id and status='ABIERTA'order by opening_id desc limit 1);return jsonb_build_object('id',id,'difference',actual-box.current_balance,'message','Caja cerrada correctamente.');else raise exception'Operación de Tesorería inválida.';end if;end$$;

create or replace function save_treasury_schedule(p_payload jsonb,p_schedule_id bigint default null)returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$declare sid bigint:=active_subsidiary_id();id bigint:=p_schedule_id;begin if id is null then insert into treasury_schedule(subsidiary_id,schedule_type,supplier_id,customer_id,supplier_invoice_id,invoice_id,due_date,planned_date,amount,currency_id,priority,status,note,created_by)values(sid,p_payload->>'type',nullif(p_payload->>'supplier_id','')::bigint,nullif(p_payload->>'customer_id','')::bigint,nullif(p_payload->>'supplier_invoice_id','')::bigint,nullif(p_payload->>'invoice_id','')::bigint,(p_payload->>'due_date')::date,(p_payload->>'planned_date')::date,(p_payload->>'amount')::numeric,(p_payload->>'currency_id')::bigint,coalesce(p_payload->>'priority','MEDIA'),coalesce(p_payload->>'status','PROGRAMADO'),p_payload->>'note',app_user_id())returning schedule_id into id;else update treasury_schedule set planned_date=(p_payload->>'planned_date')::date,amount=(p_payload->>'amount')::numeric,priority=p_payload->>'priority',status=p_payload->>'status',note=p_payload->>'note'where schedule_id=id and subsidiary_id=sid;if not found then raise exception'Programación no encontrada.';end if;end if;return jsonb_build_object('id',id,'message','Programación guardada correctamente.');end$$;
create or replace function delete_treasury_schedule(p_schedule_id bigint)returns boolean language plpgsql security definer set search_path=public as $$begin delete from treasury_schedule where schedule_id=p_schedule_id and subsidiary_id=active_subsidiary_id()and status='PROGRAMADO';if not found then raise exception'Solo se pueden eliminar programaciones pendientes.';end if;return true;end$$;
revoke all on function treasury_workspace(jsonb),save_treasury_operation(jsonb),save_treasury_schedule(jsonb,bigint),delete_treasury_schedule(bigint)from public,anon;grant execute on function treasury_workspace(jsonb),save_treasury_operation(jsonb),save_treasury_schedule(jsonb,bigint),delete_treasury_schedule(bigint)to authenticated;notify pgrst,'reload schema';
